INSERT INTO public.source (id, title, source_type, author, edition, url, note)
SELECT id, title, source_type, author, edition, url, note FROM jsonb_populate_recordset(NULL::public.source, '[{"title": "旧五代史·卷77·晋高祖纪·天福三年十一月", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/ffeb58e6e0fe058df2623e62372c88eca7addd8c/content/books/zizhi-tongjian/vol-281/year-0938/part-06/sources/library/jiuwudaishi-077-november/source.txt", "note": "《旧五代史》卷77·晋高祖纪·天福三年十一月，段落 jiu-wudaishi-205deb4a7860-p001921；已核上下文及传主，纸本及异文待核。", "id": "bcc07e25-bf22-5330-b9f9-f6f647d22193"}, {"title": "资治通鉴·后晋纪二", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/ffeb58e6e0fe058df2623e62372c88eca7addd8c/content/books/zizhi-tongjian/vol-281/year-0938/part-06/sources/library/tongjian-281-938-late-year/source.txt", "note": "《资治通鉴》后晋纪二，段落 zizhi-tongjian-a63549944a71-p003347；电子底本待考，分段待核", "id": "5e5dbf60-5de6-5c93-b202-6c331fc29781"}, {"title": "新唐书·卷101·萧仿附传", "source_type": "primary", "author": "欧阳修、宋祁", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/ffeb58e6e0fe058df2623e62372c88eca7addd8c/content/books/zizhi-tongjian/vol-281/year-0938/part-06/sources/library/xintangshu-101-xiao-fang/source.txt", "note": "《新唐书》卷101·萧仿附传，段落 xin-tangshu-685ef499825e-p027472；已核上下文及传主，纸本及异文待核。", "id": "be5388c2-d4e3-5aec-9814-055da6a39cf4"}, {"title": "新五代史·卷65·南汉世家", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/ffeb58e6e0fe058df2623e62372c88eca7addd8c/content/books/zizhi-tongjian/vol-281/year-0938/part-06/sources/library/xinwudaishi-065-bach-dang/source.txt", "note": "《新五代史》卷65·南汉世家，段落 xin-wudaishi-b08f244b9241-p003276；已核上下文及传主，纸本及异文待核。", "id": "512c2963-cd4e-5a4d-a1ad-a5643587c0c4"}, {"title": "资治通鉴·后晋纪二", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/15cac06f05420ed79060ede111d9764429048842/content/books/zizhi-tongjian/vol-281/year-0938/part-05/sources/library/tongjian-281-938-surrender-and-capital/source.txt", "note": "《资治通鉴》后晋纪二，段落 zizhi-tongjian-a63549944a71-p003346；电子底本待考，分段待核", "id": "79a65a05-76fb-56ed-8810-45f64f50d9ec"}, {"title": "旧五代史·卷77·晋高祖纪·天福三年十月", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/15cac06f05420ed79060ede111d9764429048842/content/books/zizhi-tongjian/vol-281/year-0938/part-05/sources/library/jiuwudaishi-077-october/source.txt", "note": "《旧五代史》卷77·晋高祖纪·天福三年十月，段落 jiu-wudaishi-205deb4a7860-p001920；已核上下文及传主，纸本及异文待核。", "id": "691170bd-8ab1-53f2-ae36-22ae37c78d18"}]'::jsonb)
