INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "石敬瑭", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷271贞明五年条所见人物：石敬瑭。", "biography": null, "status": "draft", "id": "bf42d98c-7477-5be1-a767-867fe26cf617"}, {"name": "吴权", "aliases": ["吳權"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "杨廷艺的旧将。938年从爱州起兵进攻皎公羡，取得交州，并在白藤江利用铁桩和潮汐击败南汉水军。生卒年本段未载。", "biography": null, "status": "draft", "id": "3d05f882-133e-5354-aa3c-d0e620ffc0ff"}, {"name": "皎公羡", "aliases": ["皎公羨"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "交州将领。《资治通鉴》记载他在937年杀死安南节度使杨廷艺并取代其职务。", "biography": null, "status": "draft", "id": "77668d4d-1def-5fe2-b80d-d256a88e8e1f"}, {"name": "杨廷艺", "aliases": ["楊廷藝"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：杨廷艺，爱州将、养假子谋复交州者。", "biography": null, "status": "draft", "id": "ab60ef4d-6704-510d-bc6a-4c62aa871399"}, {"name": "刘岩", "aliases": ["刘龑", "劉巖", "劉龑", "劉岩", "刘巖"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷267开平四年条所见人物：刘岩。", "biography": null, "status": "draft", "id": "3b676280-64ca-5ba9-b78d-c6c5f257a018"}, {"name": "刘弘操", "aliases": ["劉弘操", "刘洪操", "劉洪操"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：刘弘操，获封王爵之子。", "biography": null, "status": "draft", "id": "da4a9541-19b0-5479-be1a-f074de7470b2"}, {"name": "萧益", "aliases": ["蕭益"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "南汉崇文使，萧仿的孙子。938年南汉出兵交州时，建议谨慎进军、选用熟悉地形的向导；刘岩没有听从。生卒年未载。", "biography": null, "status": "draft", "id": "8be0c6ac-cc0d-55d7-b6d9-3e2d1dd20527"}, {"name": "侯融", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "南汉著作佐郎。曾劝刘岩停止用兵、休养民力；交州战败后，刘岩追究他的责任，打开棺木暴露遗体。劝谏和死亡的具体年月未载。", "biography": null, "status": "draft", "id": "0efb90f5-42a4-5fe5-aa0e-d8c74ffcb381"}, {"name": "萧仿", "aliases": ["蕭仿"], "era": "唐", "birth_year": null, "death_year": null, "description": "萧益的祖父。《新唐书》记他字思道，为萧悟之子，在唐代大和年间考中进士，后来担任给事中。生卒年本次未核。", "biography": null, "status": "draft", "id": "b15758c5-dd37-5c54-acab-ed5a6f617360"}, {"name": "彭氏（楚顺贤夫人）", "aliases": ["顺贤夫人彭氏", "順賢夫人彭氏"], "era": "五代十国", "birth_year": null, "death_year": 938, "description": "楚顺贤夫人。938年去世。《资治通鉴》记她治家有法，马希范对她有所畏惧；个人名字和出生年未载。", "biography": null, "status": "draft", "id": "6f9cfdb5-54d5-5a24-b44b-943f50ad0fea"}, {"name": "马希范", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷267开平三年条所见人物：马希范。", "biography": null, "status": "draft", "id": "6c13c07c-57cf-596e-9247-ba0556ac4737"}, {"name": "范延光", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷272同光元年条所见人物：范延光。", "biography": null, "status": "draft", "id": "6889e460-4b23-5243-9441-b5c3a78da98f"}, {"name": "王继鹏", "aliases": ["王繼鵬", "王昶"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：王继鹏，被任命权军府事的王子。", "biography": null, "status": "draft", "id": "94e0308c-1642-5beb-9233-76f848fff4f0"}, {"name": "卢损（后晋册礼使）", "aliases": ["卢损", "盧損"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后晋左散骑常侍。938年十一月受命为册礼使，参与后晋封王继鹏为闽国王的安排。生卒年未载。", "biography": null, "status": "draft", "id": "0c09b996-f1d4-5968-b303-4dd2f489cf1a"}, {"name": "王继恭", "aliases": ["王繼恭"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "闽国官员，937年以威武节度使身份奉闽王命向后晋报告继位并请求设立邸舍。《资治通鉴》称他为闽王王继鹏的弟弟，《新五代史》称为儿子，亲属身份存在异说。", "biography": null, "status": "draft", "id": "10a53d6a-e6d8-5230-b1aa-76b1340b24f1"}, {"name": "林恩（闽进奏官）", "aliases": ["林恩"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "闽国进奏官。938年十一月受王继鹏派遣，向后晋执政官转达拒绝册命和使者的意见。生卒年未载。", "biography": null, "status": "draft", "id": "73672be9-5a93-588b-9b22-1ea5a804738a"}, {"name": "黄讽（闽谏议大夫）", "aliases": ["黄讽", "黃諷"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "闽国谏议大夫。938年十一月与家人告别后进谏，拒绝受杖打，被王继鹏贬为平民。生卒年未载。", "biography": null, "status": "draft", "id": "199847ea-3125-539a-9a5f-8c0dcd592125"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
SELECT id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status FROM jsonb_populate_recordset(NULL::public.event, '[{"title": "石敬瑭下令大赦", "start_year": 938, "end_year": 938, "time_original": "938年十月戊戌", "dynasty": "五代十国", "description": "石敬瑭下令大赦。", "phases": [], "location_name": "五代十国", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "7b9f8f55-dbef-56ac-9fe9-bf6457ff0066"}, {"title": "吴权从爱州起兵进攻交州的皎公羡", "start_year": 938, "end_year": 938, "time_original": "938年十月条下，具体日期未载", "dynasty": "五代十国", "description": "吴权从爱州起兵进攻交州的皎公羡。", "phases": [], "location_name": "爱州、交州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "01f1bbd1-b993-5688-b229-af7265b4ce37"}, {"title": "皎公羡派使者向南汉求援并送礼", "start_year": 938, "end_year": 938, "time_original": "938年十月条下，具体日期未载", "dynasty": "五代十国", "description": "皎公羡派使者向南汉求援并送礼。", "phases": [], "location_name": "交州、南汉", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "13b1e3fb-2be3-52de-b456-fc6d34a036db"}, {"title": "刘岩任刘弘操为静海节度使，改封交王并命其救援", "start_year": 938, "end_year": 938, "time_original": "938年十月条下，具体日期未载", "dynasty": "五代十国", "description": "刘岩任刘弘操为静海节度使，改封交王并命其救援。", "phases": [], "location_name": "静海军、交州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "ca32e92c-a0f3-5dc7-8772-e23883963580"}, {"title": "刘岩亲自率军驻海门，为刘弘操声援", "start_year": 938, "end_year": 938, "time_original": "938年十月条下，具体日期未载", "dynasty": "五代十国", "descr